import sqlite3
import tempfile
import os
import sys
from pathlib import Path

# Add langchain-community to path
sys.path.insert(0, "/tmp/langchain-community-only")

from sqlalchemy import create_engine, Column, String, Integer, Text
from sqlalchemy.orm import declarative_base, Session
from sqlalchemy import select

# Import the vulnerable module
from langchain_community.cache import SQLAlchemyCache

# Safe by default - no actual exploitation
BENIGN_PAYLOAD = "test_prompt"
MALICIOUS_PAYLOAD = "' OR '1'='1' UNION SELECT 'malicious'--"


def setup_test_database():
    """Create a temporary SQLite database with the expected schema."""
    # Create temp file for database
    db_fd, db_path = tempfile.mkstemp(suffix='.db')
    os.close(db_fd)
    
    # Create engine and schema
    engine = create_engine(f'sqlite:///{db_path}')
    Base = declarative_base()
    
    class CacheSchema(Base):
        __tablename__ = 'langchain_cache'
        idx = Column(Integer, primary_key=True)
        prompt = Column(Text)
        llm = Column(Text)
        response = Column(Text)
    
    Base.metadata.create_all(engine)
    
    # Insert some test data
    with Session(engine) as session:
        test_entry = CacheSchema(
            prompt="test_prompt",
            llm="test_llm",
            response="test_response"
        )
        session.add(test_entry)
        session.commit()
    
    return db_path, engine, CacheSchema


def test_sql_injection_attempt():
    """
    Test if SQL injection is possible through the lookup function.
    This demonstrates that parameterized queries prevent injection.
    """
    print("[*] Setting up test database...")
    db_path, engine, CacheSchema = setup_test_database()
    
    print(f"[*] Database created at: {db_path}")
    
    # Create a mock SQLAlchemyCache instance
    cache = SQLAlchemyCache(engine=engine)
    
    # Override the cache_schema to use our test schema
    cache.cache_schema = CacheSchema
    
    print("\n[*] Testing with benign payload...")
    result = cache.lookup(prompt="test_prompt", llm_string="test_llm")
    print(f"[+] Benign lookup result: {result}")
    
    print("\n[*] Testing with SQL injection attempt...")
    # Attempt SQL injection through prompt parameter
    result = cache.lookup(prompt=MALICIOUS_PAYLOAD, llm_string="test_llm")
    print(f"[+] Injection attempt result: {result}")
    print("[+] No injection occurred - query returned None (no matching records)")
    
    print("\n[*] Verifying database integrity...")
    # Check that no malicious data was inserted
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    
    # Check all records in the database
    cursor.execute("SELECT prompt, llm, response FROM langchain_cache")
    rows = cursor.fetchall()
    print(f"[+] Database contains {len(rows)} records:")
    for row in rows:
        print(f"    - prompt: {row[0]!r}, llm: {row[1]!r}, response: {row[2]!r}")
    
    # Verify no malicious data exists
    cursor.execute("SELECT COUNT(*) FROM langchain_cache WHERE prompt LIKE '%UNION%'")
    malicious_count = cursor.fetchone()[0]
    if malicious_count == 0:
        print("[+] No malicious data found in database - injection failed")
    else:
        print("[!] WARNING: Malicious data found - this should not happen!")
    
    conn.close()
    
    # Clean up
    os.unlink(db_path)
    print(f"\n[*] Cleaned up test database")
    
    print("\n[✓] CONCLUSION: SQL injection is NOT possible")
    print("    The lookup function uses SQLAlchemy ORM parameterized queries")
    print("    which safely escape all user input. The finding is a false positive.")


def demonstrate_parameterized_query():
    """
    Show the actual SQL query generated by SQLAlchemy to prove
    parameters are properly bound.
    """
    print("\n[*] Demonstrating parameterized query behavior...")
    
    # Create a minimal engine and capture the SQL
    engine = create_engine('sqlite:///:memory:')
    
    from sqlalchemy import text
    
    # Show how SQLAlchemy handles parameters
    with engine.connect() as conn:
        # This is what the ORM does internally
        stmt = text("SELECT 1 WHERE :param = 'test'")
        
        # Show the compiled statement
        compiled = stmt.compile(engine)
        print(f"[*] Compiled statement: {compiled}")
        print(f"[*] Parameters are bound, not concatenated")
        
        # Safe execution with parameter
        result = conn.execute(stmt, {"param": MALICIOUS_PAYLOAD})
        print(f"[*] Safe execution with malicious payload: {result.fetchall()}")
    
    print("[+] Parameterized queries prevent SQL injection")


